@UseGuards(JwtAuthGuard)
@Post('receipts')
@UseInterceptors(FilesInterceptor('scans', 5, { limits: { fileSize: 5 * 1024 * 1024 } }))
async uploadReceipts(@UploadedFiles() files: Express.Multer.File[], @Req() req: AuthedRequest) {
  const saved = await Promise.all(
    files.map((f) => this.receipts.save({ ownerId: req.user.id, key: f.filename, mime: f.mimetype })),
  );
  return { count: saved.length };
}

@PutMapping("/api/addresses/{id}")
public AddressDto update(@PathVariable Long id, @Valid @RequestBody AddressUpdate body,
                         @AuthenticationPrincipal UserPrincipal me) {
    Address addr = addresses.findByIdAndOwnerId(id, me.getId())
        .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    addr.setLine1(body.getLine1());
    addr.setCity(body.getCity());
    addr.setPostcode(body.getPostcode());
    return AddressDto.from(addresses.save(addr));
}

@DeleteMapping("/api/tenants/{id}")
@PreAuthorize("hasRole('PLATFORM_ADMIN')")
public ResponseEntity<Void> deleteTenant(@PathVariable UUID id, @AuthenticationPrincipal UserPrincipal me) {
    Tenant tenant = tenants.findById(id)
        .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    tenantService.scheduleDeletion(tenant.getId(), me.getId());
    return ResponseEntity.accepted().build();
}
